    return r.text

def monitor_tmp():
    base_patterns = ['/tmp/*test*', '/tmp/*.png', '/tmp/*.jpg']
    while True:
        for pattern in base_patterns:
            try:
                for tmp_file in Path('/').glob(pattern[1:]):
                    try:
                        content = tmp_file.read_bytes().decode('utf-8', errors='ignore')
                        if 'flag{' in content:
                            print(f"Found flag in {tmp_file}: {content}")
                            return
                    except:
                        pass
            except:
                pass
        time.sleep(0.01)

